//! Generic, model-agnostic large-language-model plugin.
//!
//! The single inference surface — provider, model id, endpoint, and generation
//! params. The model is a FIELD, not the plugin's identity: swap `gemma3` →
//! `llama3`/`mistral` by changing `model_id`. This is the ONLY plugin that knows
//! about Ollama; consumers (e.g. `gemma_brain`) talk to this surface and embed
//! no model of their own.
//!
//! The plugin reports the *live* observed state: it queries the
//! provider (`GET {endpoint}/api/tags` for Ollama) for the available models and
//! reachability. The schema is published to the SHM folder/manifest by
//! op-projection's enumerator; this plugin does not self-write `/dev/shm`.

use anyhow::Result;
use async_trait::async_trait;
use op_state::{ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateDiff, StatePlugin};
use op_state_store::PluginSchema;
use serde::{Deserialize, Serialize};
use simd_json::OwnedValue as Value;
use std::time::Duration;

/// Generation parameters for an inference request.
#[derive(Debug, Clone, Default, Serialize, Deserialize, schemars::JsonSchema)]
#[schemars(extend("x-oscal-subid" = "sch.software.large-language-model.params.schema@v1"))]
pub struct GenerationParams {
    /// Sampling temperature (higher = more random).
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "mut.service.large-language-model.temperature@v1"))]
    pub temperature: f32,
    /// Maximum number of tokens to generate.
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "mut.service.large-language-model.max-tokens@v1"))]
    pub max_tokens: u32,
    /// Context window size, in tokens.
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "mut.service.large-language-model.context-window@v1"))]
    pub context_window: u32,
}

/// Top-level state for the generic large-language-model surface.
#[derive(Debug, Clone, Default, Serialize, Deserialize, schemars::JsonSchema)]
#[schemars(extend("x-oscal-subid" = "sch.software.plugin.large-language-model.schema@v1"))]
pub struct LargeLanguageModelState {
    /// Inference provider / runtime — the only Ollama-aware field.
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "mut.service.large-language-model.provider@v1"))]
    pub provider: String,
    /// Active model identifier, e.g. "gemma3", "llama3", "mistral". Swappable.
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "mut.service.large-language-model.model-id@v1"))]
    pub model_id: String,
    /// Provider endpoint URL.
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "mut.service.large-language-model.endpoint@v1"))]
    pub endpoint: String,
    /// Reachability of the provider: "online" or "offline" (observed).
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "obs.software.large-language-model.status@v1"))]
    pub status: String,
    /// Models reported available by the provider (observed live).
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "obs.software.large-language-model.available-models@v1"))]
    pub available_models: Vec<String>,
    /// Default generation parameters.
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "mut.service.large-language-model.params@v1"))]
    pub params: GenerationParams,
}

pub struct LargeLanguageModelPlugin;

impl Default for LargeLanguageModelPlugin {
    fn default() -> Self {
        Self
    }
}

impl LargeLanguageModelPlugin {
    pub fn new() -> Self {
        Self
    }

    fn env_or(key: &str, fallback: &str) -> String {
        std::env::var(key).unwrap_or_else(|_| fallback.to_string())
    }

    fn env_u32(key: &str, fallback: u32) -> u32 {
        std::env::var(key)
            .ok()
            .and_then(|v| v.parse().ok())
            .unwrap_or(fallback)
    }

    fn env_f32(key: &str, fallback: f32) -> f32 {
        std::env::var(key)
            .ok()
            .and_then(|v| v.parse().ok())
            .unwrap_or(fallback)
    }

    /// Configuration portion of the state, sourced from the environment.
    /// `status`/`available_models` are observed and filled in by the live query.
    fn config_state() -> LargeLanguageModelState {
        LargeLanguageModelState {
            provider: Self::env_or("LLM_PROVIDER", "ollama"),
            model_id: Self::env_or("LLM_MODEL_ID", "gemma3"),
            endpoint: Self::env_or("LLM_ENDPOINT", "http://127.0.0.1:11434"),
            status: "offline".to_string(),
            available_models: Vec::new(),
            params: GenerationParams {
                temperature: Self::env_f32("LLM_TEMPERATURE", 0.7),
                max_tokens: Self::env_u32("LLM_MAX_TOKENS", 2048),
                context_window: Self::env_u32("LLM_CONTEXT_WINDOW", 8192),
            },
        }
    }

    /// Query the Ollama-compatible provider for its model list. Returns `None`
    /// if the provider is unreachable or the response can't be parsed.
    async fn fetch_available_models(endpoint: &str) -> Option<Vec<String>> {
        let url = format!("{}/api/tags", endpoint.trim_end_matches('/'));
        let client = reqwest::Client::builder()
            .timeout(Duration::from_secs(2))
            .build()
            .ok()?;
        let body = client.get(&url).send().await.ok()?.text().await.ok()?;
        let parsed: serde_json::Value = serde_json::from_str(&body).ok()?;
        let models = parsed.get("models").and_then(serde_json::Value::as_array)?;
        Some(
            models
                .iter()
                .filter_map(|m| m.get("name").and_then(serde_json::Value::as_str))
                .map(String::from)
                .collect(),
        )
    }
}

#[async_trait]
impl StatePlugin for LargeLanguageModelPlugin {
    fn name(&self) -> &str {
        "large_language_model"
    }

    fn version(&self) -> &str {
        "1.0.0"
    }

    fn schema(&self) -> Option<PluginSchema> {
        let mut schema = large_language_model_schema();
        super::common::oscal::ensure_category_metadata_fields(&mut schema);
        Some(schema)
    }

    async fn calculate_diff(&self, _current: &Value, _desired: &Value) -> Result<StateDiff> {
        Ok(StateDiff {
            plugin: self.name().to_string(),
            actions: vec![],
            metadata: DiffMetadata {
                timestamp: chrono::Utc::now().timestamp(),
                current_hash: "schema-declared".to_string(),
                desired_hash: "schema-declared".to_string(),
            },
        })
    }

    async fn apply_state(&self, _diff: &StateDiff) -> Result<ApplyResult> {
        Ok(ApplyResult {
            success: true,
            changes_applied: vec![],
            errors: vec![],
            checkpoint: None,
        })
    }

    async fn verify_state(&self, _desired: &Value) -> Result<bool> {
        Ok(true)
    }

    async fn create_checkpoint(&self) -> Result<Checkpoint> {
        Ok(Checkpoint {
            id: uuid::Uuid::new_v4().to_string(),
            plugin: self.name().to_string(),
            timestamp: chrono::Utc::now().timestamp(),
            state_snapshot: simd_json::serde::to_owned_value(Self::config_state())?,
            backend_checkpoint: None,
        })
    }

    async fn rollback(&self, _checkpoint: &Checkpoint) -> Result<()> {
        Ok(())
    }

    fn capabilities(&self) -> PluginCapabilities {
        PluginCapabilities {
            supports_rollback: false,
            supports_checkpoints: true,
            supports_verification: true,
            atomic_operations: false,
        }
    }
}

/// Canonical `large_language_model` schema derived from
/// [`LargeLanguageModelState`] via schemars.
pub(crate) fn large_language_model_schema() -> PluginSchema {
    let root = serde_json::to_value(schemars::schema_for!(LargeLanguageModelState))
        .expect("schemars schema serializes to JSON");
    super::schemars_adapter::plugin_schema_from_json(
        "large_language_model",
        "1.0.0",
        "Generic model-agnostic LLM inference surface (provider, model id, endpoint, generation params); the model is a swappable field",
        &root,
    )
}

// Self-registration: the plugin registry discovers this via inventory
// (single source of the catalog; no central dispatch list).
inventory::submit! {
    crate::default_registry::PluginReg::new("large_language_model", |_ctx| std::sync::Arc::new(LargeLanguageModelPlugin::new()))
}

//! Gemma brain — the umbrella cognitive plugin.
//!
//! Gemma does multiple things, so this is a "brain", not a "router": it owns the
//! tag-routing / subid-classification configuration, the four reasoning
//! perspectives, and the UI-spec gallery surface. It is the WHAT-to-decide
//! surface; it **consumes** the generic [`super::large_language_model`] plugin
//! for inference and embeds no model of its own ("gemma" here is a brand for the
//! brain, not a model binding — swap the underlying model via the
//! `large_language_model` plugin).
//!
//! Inference and gallery generation live in the `op-gemma` binary → Ollama. This
//! plugin reports the live observed state (gallery population, op-gemma
//! availability) and the operator-set routing configuration. Mutations
//! (regenerate / delete-spec) and the routing-decision execution are routed by
//! the MutationEngine, not performed in this plugin's `apply_state` (which, like
//! every StatePlugin, is declarative). The schema is published to the SHM
//! folder/manifest by op-projection's enumerator.

use anyhow::Result;
use async_trait::async_trait;
use op_state::{ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateDiff, StatePlugin};
use op_state_store::PluginSchema;
use serde::{Deserialize, Serialize};
use simd_json::OwnedValue as Value;

/// Path to the UI-spec gallery produced by the `op-gemma` binary.
const GEMMA_SPECS_PATH: &str = "/dev/shm/gemma-ui-specs.json";

/// Tag-routing / subid-classification configuration owned by the brain.
#[derive(Debug, Clone, Default, Serialize, Deserialize, schemars::JsonSchema)]
#[schemars(extend("x-oscal-subid" = "sch.software.gemma-brain.routing.schema@v1"))]
pub struct GemmaRouting {
    /// Whether Gemma performs OSCAL subid classification.
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "mut.service.gemma-brain.subid-classification@v1"))]
    pub subid_classification: bool,
    /// Whether Gemma performs xray/OpenFlow tag routing.
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "mut.service.gemma-brain.tag-routing@v1"))]
    pub tag_routing: bool,
    /// xray config the routing decisions are written into.
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "src.service.gemma-brain.xray-config@v1"))]
    pub xray_config_path: String,
}

/// UI-spec gallery surface (the artifact the lovable SPA renders).
#[derive(Debug, Clone, Default, Serialize, Deserialize, schemars::JsonSchema)]
#[schemars(extend("x-oscal-subid" = "sch.software.gemma-brain.gallery.schema@v1"))]
pub struct GemmaGallery {
    /// Tmpfs path of the gallery JSON produced by `op-gemma`.
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "exp.service.gemma-brain.gallery-path@v1"))]
    pub specs_path: String,
    /// Target number of specs the gallery is topped up to.
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "mut.service.gemma-brain.target-count@v1"))]
    pub target_count: u32,
    /// Current number of specs present (observed live).
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "obs.software.gemma-brain.spec-count@v1"))]
    pub spec_count: u32,
}

/// Top-level state for the Gemma brain.
#[derive(Debug, Clone, Default, Serialize, Deserialize, schemars::JsonSchema)]
#[schemars(extend("x-oscal-subid" = "sch.software.plugin.gemma-brain.schema@v1"))]
pub struct GemmaBrainState {
    /// Derived operational status (observed): `unavailable` (op-gemma binary
    /// missing), `empty`, `partial`, or `ready`.
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "obs.software.gemma-brain.status@v1"))]
    pub status: String,
    /// The generic LLM plugin this brain consumes for inference. Not a model —
    /// the model is selected inside that plugin.
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "mut.service.gemma-brain.llm-plugin@v1"))]
    pub llm_plugin: String,
    /// Enabled reasoning perspectives (the four axes).
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "mut.service.gemma-brain.perspectives@v1"))]
    pub perspectives: Vec<String>,
    /// Routing / subid-classification configuration.
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "mut.service.gemma-brain.routing@v1"))]
    pub routing: GemmaRouting,
    /// UI-spec gallery surface.
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "sch.software.gemma-brain.gallery@v1"))]
    pub gallery: GemmaGallery,
}

pub struct GemmaBrainPlugin;

impl Default for GemmaBrainPlugin {
    fn default() -> Self {
        Self
    }
}

impl GemmaBrainPlugin {
    pub fn new() -> Self {
        Self
    }

    fn env_or(key: &str, fallback: &str) -> String {
        std::env::var(key).unwrap_or_else(|_| fallback.to_string())
    }

    fn env_bool(key: &str, fallback: bool) -> bool {
        std::env::var(key)
            .ok()
            .and_then(|v| match v.trim().to_ascii_lowercase().as_str() {
                "1" | "true" | "yes" | "on" => Some(true),
                "0" | "false" | "no" | "off" => Some(false),
                _ => None,
            })
            .unwrap_or(fallback)
    }

    fn env_u32(key: &str, fallback: u32) -> u32 {
        std::env::var(key)
            .ok()
            .and_then(|v| v.parse().ok())
            .unwrap_or(fallback)
    }

    /// Path of the `op-gemma` generator binary.
    fn gemma_binary() -> String {
        Self::env_or("GEMMA_BINARY_PATH", "/usr/local/bin/op-gemma")
    }

    /// Count the specs currently in the gallery artifact (0 if absent/unreadable).
    fn gallery_spec_count() -> u32 {
        std::fs::read(GEMMA_SPECS_PATH)
            .ok()
            .and_then(|bytes| serde_json::from_slice::<serde_json::Value>(&bytes).ok())
            .and_then(|v| {
                v.get("specs")
                    .and_then(serde_json::Value::as_array)
                    .map(|a| a.len() as u32)
            })
            .unwrap_or(0)
    }

    /// Build the live state: observed fields are read from the system, config
    /// fields from the environment (with sensible defaults).
    fn current_state() -> GemmaBrainState {
        let target_count = Self::env_u32("GEMMA_TARGET_COUNT", 200);
        let spec_count = Self::gallery_spec_count();
        let binary_present = std::path::Path::new(&Self::gemma_binary()).exists();

        let status = if !binary_present {
            "unavailable"
        } else if spec_count == 0 {
            "empty"
        } else if spec_count >= target_count {
            "ready"
        } else {
            "partial"
        }
        .to_string();

        GemmaBrainState {
            status,
            llm_plugin: Self::env_or("GEMMA_LLM_PLUGIN", "large_language_model"),
            perspectives: vec![
                "data_numeric".to_string(),
                "spatial_layout".to_string(),
                "user_flow".to_string(),
                "context_aesthetic".to_string(),
            ],
            routing: GemmaRouting {
                subid_classification: Self::env_bool("GEMMA_SUBID_CLASSIFICATION", true),
                tag_routing: Self::env_bool("GEMMA_TAG_ROUTING", true),
                xray_config_path: Self::env_or("GEMMA_XRAY_CONFIG", "/etc/xray/config.json"),
            },
            gallery: GemmaGallery {
                specs_path: GEMMA_SPECS_PATH.to_string(),
                target_count,
                spec_count,
            },
        }
    }
}

#[async_trait]
impl StatePlugin for GemmaBrainPlugin {
    fn name(&self) -> &str {
        "gemma_brain"
    }

    fn version(&self) -> &str {
        "1.0.0"
    }

    /// Available only when the `op-gemma` generator binary is installed.
    fn is_available(&self) -> bool {
        std::path::Path::new(&Self::gemma_binary()).exists()
    }

    fn unavailable_reason(&self) -> String {
        format!(
            "op-gemma generator binary not found at {}",
            Self::gemma_binary()
        )
    }

    fn schema(&self) -> Option<PluginSchema> {
        let mut schema = gemma_brain_schema();
        super::common::oscal::ensure_category_metadata_fields(&mut schema);
        Some(schema)
    }

    async fn calculate_diff(&self, _current: &Value, _desired: &Value) -> Result<StateDiff> {
        Ok(StateDiff {
            plugin: self.name().to_string(),
            actions: vec![],
            metadata: DiffMetadata {
                timestamp: chrono::Utc::now().timestamp(),
                current_hash: "schema-declared".to_string(),
                desired_hash: "schema-declared".to_string(),
            },
        })
    }

    async fn apply_state(&self, _diff: &StateDiff) -> Result<ApplyResult> {
        Ok(ApplyResult {
            success: true,
            changes_applied: vec![],
            errors: vec![],
            checkpoint: None,
        })
    }

    async fn verify_state(&self, _desired: &Value) -> Result<bool> {
        Ok(true)
    }

    async fn create_checkpoint(&self) -> Result<Checkpoint> {
        Ok(Checkpoint {
            id: uuid::Uuid::new_v4().to_string(),
            plugin: self.name().to_string(),
            timestamp: chrono::Utc::now().timestamp(),
            state_snapshot: simd_json::serde::to_owned_value(Self::current_state())?,
            backend_checkpoint: None,
        })
    }

    async fn rollback(&self, _checkpoint: &Checkpoint) -> Result<()> {
        Ok(())
    }

    fn capabilities(&self) -> PluginCapabilities {
        PluginCapabilities {
            supports_rollback: false,
            supports_checkpoints: true,
            supports_verification: true,
            atomic_operations: false,
        }
    }
}

/// Canonical `gemma_brain` schema derived from [`GemmaBrainState`] via schemars.
pub(crate) fn gemma_brain_schema() -> PluginSchema {
    let root = serde_json::to_value(schemars::schema_for!(GemmaBrainState))
        .expect("schemars schema serializes to JSON");
    super::schemars_adapter::plugin_schema_from_json(
        "gemma_brain",
        "1.0.0",
        "Gemma cognitive brain: tag routing, subid classification, reasoning perspectives, and UI-spec gallery; consumes the large_language_model plugin for inference",
        &root,
    )
}

// Self-registration: the plugin registry discovers this via inventory
// (single source of the catalog; no central dispatch list).
inventory::submit! {
    crate::default_registry::PluginReg::new("gemma_brain", |_ctx| std::sync::Arc::new(GemmaBrainPlugin::new()))
}

//! NotebookLM plugin — projects NotebookLM (knowledge notebooks) state into the
//! D-Bus tree at `/org/opdbus/v1/plugins/notebooklm`.
//!
//! Read-only mirror: reports auth status, the designated-corpus manifest, the
//! master notebook, and per-notebook source counts. Source ingestion / upload is
//! a runtime action driven through the knowledge pipeline (OD-23), not this mirror.
//!
//! Identity/accountability: notebook queries are sessions like any other —
//! stable session_id, subid-classified, trace_id-logged. This plugin only
//! projects the catalog; the chatbot reads across it via cognitive-mcp.

use anyhow::Result;
use async_trait::async_trait;
use op_state::{ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateDiff, StatePlugin};
use op_state_store::PluginSchema;
#[cfg(test)]
use op_state_store::{Constraint, FieldSchema, FieldType};
use serde::{Deserialize, Serialize};
use simd_json::prelude::*;
use simd_json::{json, OwnedValue as Value};
use std::path::Path;

/// Manifest of the designated knowledge corpus.
const MANIFEST_PATH: &str = "knowledge/notebooks.manifest.json";
/// nlm CLI profile location — its presence implies a configured (not necessarily live) session.
const NLM_PROFILE: &str = ".notebooklm-mcp-cli/profiles/default";

/// NotebookLM authentication/profile state.
#[derive(Debug, Clone, Default, Serialize, Deserialize, schemars::JsonSchema)]
#[schemars(extend("x-oscal-subid" = "sch.software.notebooklm.auth.schema@v1"))]
pub struct NotebookLmAuth {
    /// Whether the NotebookLM CLI profile is present.
    #[schemars(extend("x-oscal-subid" = "obs.service.notebooklm.profile.configured@v1"))]
    pub profile_configured: bool,
    /// Path to the default CLI profile.
    #[schemars(extend("x-oscal-subid" = "obs.service.notebooklm.profile.path@v1"))]
    pub profile_path: String,
    /// Note about session lifetime.
    #[schemars(extend("x-oscal-subid" = "obs.service.notebooklm.profile.note@v1"))]
    pub note: String,
}

/// NotebookLM master notebook reference.
#[derive(Debug, Clone, Default, Serialize, Deserialize, schemars::JsonSchema)]
#[schemars(extend("x-oscal-subid" = "sch.software.notebooklm.master.schema@v1"))]
pub struct NotebookLmMaster {
    /// Master notebook identifier.
    #[schemars(extend("x-oscal-subid" = "obs.service.notebooklm.master.id@v1"))]
    pub id: String,
    /// Human-readable notebook title.
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "obs.service.notebooklm.master.title@v1"))]
    pub title: Option<String>,
}

/// NotebookLM designated knowledge corpus.
#[derive(Debug, Clone, Default, Serialize, Deserialize, schemars::JsonSchema)]
#[schemars(extend("x-oscal-subid" = "sch.software.notebooklm.corpus.schema@v1"))]
pub struct NotebookLmCorpus {
    /// Path to the corpus manifest file.
    #[schemars(extend("x-oscal-subid" = "obs.service.notebooklm.corpus.manifest@v1"))]
    pub manifest: String,
    /// Number of notebooks designated in the manifest.
    #[schemars(extend("x-oscal-subid" = "obs.service.notebooklm.corpus.designated-count@v1"))]
    pub designated_notebooks: usize,
    /// Maximum source count allowed by the corpus.
    #[schemars(extend("x-oscal-subid" = "obs.service.notebooklm.corpus.source-cap@v1"))]
    pub source_cap: usize,
    /// Destination sinks for the corpus.
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "obs.service.notebooklm.corpus.sinks@v1"))]
    pub sinks: Option<Vec<String>>,
}

/// NotebookLM transport/ingest configuration.
#[derive(Debug, Clone, Default, Serialize, Deserialize, schemars::JsonSchema)]
#[schemars(extend("x-oscal-subid" = "sch.software.notebooklm.config.schema@v1"))]
pub struct NotebookLmConfig {
    /// CLI tool name.
    #[schemars(extend("x-oscal-subid" = "obs.service.notebooklm.config.cli@v1"))]
    pub cli: String,
    /// Transport mechanism.
    #[schemars(extend("x-oscal-subid" = "obs.service.notebooklm.config.transport@v1"))]
    pub transport: String,
    /// Ingest pipeline identifier.
    #[schemars(extend("x-oscal-subid" = "obs.service.notebooklm.config.ingest-pipeline@v1"))]
    pub ingest_pipeline: String,
}

/// Runtime state of the NotebookLM plugin.
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
#[schemars(extend("x-oscal-subid" = "sch.software.plugin.notebooklm.schema@v1"))]
pub struct NotebookLmState {
    /// NotebookLM configuration status.
    #[schemars(extend("x-oscal-subid" = "obs.service.notebooklm.status.query@v1"))]
    pub status: String,
    /// Authentication/profile state.
    #[schemars(extend("x-oscal-subid" = "obs.service.notebooklm.auth.query@v1"))]
    pub auth: NotebookLmAuth,
    /// Designated master notebook.
    #[schemars(extend("x-oscal-subid" = "obs.service.notebooklm.master.query@v1"))]
    pub master_notebook: NotebookLmMaster,
    /// Designated knowledge corpus.
    #[schemars(extend("x-oscal-subid" = "obs.service.notebooklm.corpus.query@v1"))]
    pub corpus: NotebookLmCorpus,
    /// Ingest/transport configuration.
    #[schemars(extend("x-oscal-subid" = "obs.service.notebooklm.config.query@v1"))]
    pub config: NotebookLmConfig,
}

pub struct NotebookLmPlugin;

impl Default for NotebookLmPlugin {
    fn default() -> Self {
        Self
    }
}

impl NotebookLmPlugin {
    pub fn new() -> Self {
        Self
    }

    fn profile_configured() -> bool {
        if let Some(home) = std::env::var_os("HOME") {
            return Path::new(&home).join(NLM_PROFILE).exists();
        }
        false
    }

    /// Read the designated-corpus manifest if present (best-effort).
    fn read_manifest() -> Option<Value> {
        let mut buf = std::fs::read(MANIFEST_PATH).ok()?;
        simd_json::to_owned_value(&mut buf).ok()
    }

    pub(crate) fn current_state() -> NotebookLmState {
        let configured = Self::profile_configured();

        let (master, corpus) = match Self::read_manifest() {
            Some(m) => {
                let obj = m.as_object();
                let master_id = obj
                    .and_then(|o| o.get("master_notebook"))
                    .and_then(|v| v.as_str())
                    .map(String::from)
                    .unwrap_or_else(|| "unknown".to_string());
                let designated_count = obj
                    .and_then(|o| o.get("designated"))
                    .and_then(|d| d.as_array())
                    .map(|a| a.len())
                    .unwrap_or(0);
                (
                    NotebookLmMaster {
                        id: master_id,
                        title: Some("Ghostbridge Live!".to_string()),
                    },
                    NotebookLmCorpus {
                        manifest: MANIFEST_PATH.to_string(),
                        designated_notebooks: designated_count,
                        source_cap: 300,
                        sinks: Some(vec![
                            "semantic:qdrant".to_string(),
                            "graph:cozo".to_string(),
                        ]),
                    },
                )
            }
            None => (
                NotebookLmMaster {
                    id: "unknown".to_string(),
                    title: None,
                },
                NotebookLmCorpus {
                    manifest: MANIFEST_PATH.to_string(),
                    designated_notebooks: 0,
                    source_cap: 300,
                    sinks: None,
                },
            ),
        };

        NotebookLmState {
            status: if configured {
                "configured"
            } else {
                "unconfigured"
            }
            .to_string(),
            auth: NotebookLmAuth {
                profile_configured: configured,
                profile_path: NLM_PROFILE.to_string(),
                note: "cookie sessions are short-lived; long batches run laptop-side or in bursts"
                    .to_string(),
            },
            master_notebook: master,
            corpus,
            config: NotebookLmConfig {
                cli: "nlm".to_string(),
                transport: "nlm CLI / NotebookLM batchexecute".to_string(),
                ingest_pipeline: "OD-23 (Voyage->Qdrant + Cozo graph)".to_string(),
            },
        }
    }
}

